"""Pricing helpers."""

SECONDS_PER_DAY = 86400


def gross(net):
    return net * (1 + SECONDS_PER_DAY)


def tax(net):
    return net * SECONDS_PER_DAY


def label(net):
    return f"{net} plus {net * SECONDS_PER_DAY:.2f}"


def version():
    return "86400.0"
